const [entry,setEntry]=useState<any>(null);const [liveResults,setLiveResults]=useState<any[]>([]);useEffect(()=>{if(!joinPath)return;request(`/join/${encodeURIComponent(joinCode)}`).then(setEntry).catch(notify)},[joinCode]);useLive(entry?.session?.id,(s)=>{setEntry((old:any)=>({...old,session:s.session,activity:s.activities?.[0]||null}));setLiveResults(s.results||[])});useEffect(()=>{setAnswer('');setSent(false);setRatingSent([]);setRatingComments({});setReactionSent(false)},[entry?.activity?.id]);
async function refreshAssets(){if(!selected)return;try{setAssets(await request(`/sessions/${selected}/assets`))}catch(e){notify(e)}}
async function uploadAsset(file:File|undefined){if(!file||!selected)return;setAssetBusy(true);try{
 const allowed=['image/png','image/jpeg','image/gif','image/webp','application/pdf','video/mp4','video/webm'];
 if(!allowed.includes(file.type))throw Error('Formato non supportato');
 // The server enforces the administrator's configured size limit.
 const res=await fetch(`/api/sessions/${selected}/assets`,{method:'POST',credentials:'include',headers:{'Content-Type':file.type},body:file});
 if(!res.ok)throw Error(`Upload HTTP ${res.status}: ${await res.text()}`);
 await refreshAssets();setNotice(lang==='it'?'File caricato':'Asset uploaded');
 }catch(e){notify(e)}finally{setAssetBusy(false)}}
async function deleteAsset(id:string){if(!window.confirm(lang==='it'?'Eliminare definitivamente il file?':'Delete this file permanently?'))return;try{
 await request(`/sessions/${selected}/assets/${id}`,'DELETE');await refreshAssets();
 }catch(e){notify(e)}}
async function duplicateSelected(){try{const result=await request<{id:string}>(`/sessions/${selected}/duplicate`,'POST');await load();setSelected(result.id);setNotice('Sessione duplicata senza risultati precedenti')}catch(e){notify(e)}}
async function importSessionFile(file:File|undefined){if(!file)return;try{if(file.size>2*1024*1024)throw Error('JSON oltre 2 MB');const body=JSON.parse(await file.text());const r=await request<{id:string}>('/sessions/import','POST',body);await load();setSelected(r.id);setNotice('Definizione sessione importata')}catch(e){notify(e)}}
async function refreshCollaborators(){try{setCoPresenters(await request(`/sessions/${selected}/presenters`))}catch(e){notify(e)}}
async function addCollaborator(){try{await request(`/sessions/${selected}/presenters`,'POST',{email:coEmail.trim()});setCoEmail('');await refreshCollaborators()}catch(e){notify(e)}}
async function removeCollaborator(uid:string){if(!window.confirm('Rimuovere il co-presentatore?'))return;try{await request(`/sessions/${selected}/presenters/${uid}`,'DELETE');await refreshCollaborators()}catch(e){notify(e)}}
function beginActivityEdit(a:Activity){setEditingActivity(a.id);setEditTitle(a.title);setEditOpts(a.options.map(o=>`${o.id}|${o.label}`).join('\n'));setEditCorrect((a as any).correct_option_id||'')}
async function saveActivityEdit(){try{const original=snap?.activities.find(a=>a.id===editingActivity);if(!original)return;const next=editOpts.split('\n').filter(x=>x.trim()).map(x=>{const pos=x.indexOf('|');return {id:pos<0?'':x.slice(0,pos).trim(),label:pos<0?x.trim():x.slice(pos+1).trim()}});if(next.some(x=>!x.id||!x.label))throw Error('Ogni opzione deve conservare il suo ID: ID|testo');await request(`/sessions/${selected}/activities/${editingActivity}`,'PATCH',{title:editTitle,options:next,correct_option_id:original.type==='quiz'?editCorrect:null});setEditingActivity('');setSnap(await request(`/sessions/${selected}`))}catch(e){notify(e)}}
async function invalidateActivity(a:Activity){if(!window.confirm('Invalidare tutte le risposte di questa attività? L’operazione è tracciata.'))return;try{await request(`/sessions/${selected}/activities/${a.id}/invalidate`,'POST');setSnap(await request(`/sessions/${selected}`))}catch(e){notify(e)}}
async function requestPasswordRecovery(){try{await request('/auth/password-reset/request','POST',{email});setNotice(lang==='it'?'Se l’account è registrato, riceverai un link di recupero.':'If the account exists, a recovery link will be emailed.')}catch(e){notify(e)}}
